Ltac zto pc := repeat (lazymatch goal with |- evt _ _ (MS _ _ (Z_to_bv 64 pc) _ _ _ _) => fail | _ => zstep end).

Section CANSEC1. Context {rc : runConstT}.
Section X4S1.
  Variables (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32) (m0 : fmem).
  Variables (DST dcap SS DT mtl tl lo : Z) (src : list Z) (cells : list deltX1) (cbs : list byte).
  Notation SP := (bv_unsigned sp).
  Notation n := (zlen src).
  Hypothesis TOK : x1_table_ok cells tl.
  Hypothesis ECB : cbs = firstn (Z.to_nat (2 * 2^tl)) (x1_bytes' cells).
  Hypothesis LCB : zlen cbs = 2 * 2^tl.
  Hypothesis MTL : 1 <= mtl <= 12.
  Hypothesis TLM : tl <= mtl + 1.
  Hypothesis D0 : 0 <= DST.
  Hypothesis DP : 0 < dcap -> 8 <= DST.
  Hypothesis DC : 0 <= dcap < 2^32.
  Hypothesis DL : DST + dcap <= lo.
  Hypothesis S0 : 16 <= SS.
  Hypothesis SL : SS + n <= lo.
  Hypothesis NSM : n < 2^26.
  Hypothesis BYS : Forall (fun c => 0 <= c < 256) src.
  Hypothesis DT0 : 0 < DT.
  Hypothesis CBL : DT + 4 + 2 * 2^tl <= lo.
  Hypothesis DJ1 : DT + 4 + 2 * 2^tl <= DST \/ DST + dcap <= DT.
  Hypothesis DJ3 : DST + dcap <= SS \/ SS + n <= DST.
  Hypothesis LOS : lo <= SP - 4096.
  Hypothesis SP16 : SP mod 16 = 0.
  Hypothesis SP47 : SP <= 2^47.

  Notation POST := (huf_dec_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc DST dcap lo m0).
  Notation XB l := (l ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc m0 DST dcap SS DT mtl tl lo src cells cbs
                      TOK ECB LCB MTL TLM D0 DP DC DL S0 SL NSM BYS DT0 CBL DJ1 DJ3 LOS SP16 SP47) (only parsing).
  Notation X4F' mm spl bd4 := (X4F ra sp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 m0 DST dcap SS DT lo src cbs mm spl bd4).

  Variables (L1 L2 L3 L4 SEG : Z).
  Notation O2 := (6 + L1). Notation O3 := (6 + L1 + L2). Notation O4 := (6 + L1 + L2 + L3).
  Hypothesis HL : 1 <= L1 /\ 1 <= L2 /\ 1 <= L3 /\ 1 <= L4 /\ 6 + L1 + L2 + L3 + L4 <= n.
  Hypothesis HQ : 0 < SEG /\ 3 * SEG <= dcap /\ 4 <= dcap.
  Notation A1 l := (XB l L1 L2 L3 L4 SEG HL HQ) (only parsing).
  Notation LOOPK' q := (LOOPK ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc m0 DST dcap SS DT mtl tl lo src cbs L1 L2 L3 L4 SEG q).

  (* [comment removed for export] *)
  Notation SPL1 v48 v72 b2 j0 :=
    [CB 8 j0; C8 (Z_to_bv 64 (SS + 6)); C8 (Z_to_bv 64 (SS + O2)); C8 (Z_to_bv 64 (DST + dcap)); C8 (Z_to_bv 64 (DST + SEG));
     C8 (Z_to_bv 64 (tl + 256 * mtl)); C8 (Z_to_bv 64 v48); C8 (Z_to_bv 64 (DST + 3 * SEG)); C8 (Z_to_bv 64 (SS + O3));
     C8 (Z_to_bv 64 v72); C8 (Z_to_bv 64 (DST + 2 * SEG)); C8 (Z_to_bv 64 (SS + O4 + 8)); C8 (Z_to_bv 64 dcap);
     C8 (Z_to_bv 64 (3 * SEG)); C8 (Z_to_bv 64 (2 * SEG)); C8 (Z_to_bv 64 (DST + dcap - 3)); C8 (Z_to_bv 64 (SS + 14));
     C8 (Z_to_bv 64 (SS + O2 + 8)); C8 (Z_to_bv 64 (SS + O3 + 8)); C8 (Z_to_bv 64 b2)].

  (* [comment removed for export] *)
  Lemma x4s1_n2 : forall q p1 p2 p3 p4 bc1 bc2 u3 w3 u4 w4 st1 v48 v72 b2x c4x bc4x ptr4x mm j0 jp
                         (t1 a3 a4 a5 x19 x20 x22 x26 x27 t6 : word),
    LOOPK' q ->
    X4F' mm (SPL1 v48 v72 b2x j0) (BD4 c4x bc4x ptr4x (SS + O4) jp) ->
    0 <= q -> q + 3 * SEG + 4 <= dcap ->
    AFT L1 p1 bc1 st1 -> AFT L2 p2 bc2 3 -> 0 <= u3 -> 0 <= w3 -> BEF L3 p3 (u3 + w3) -> 0 <= u4 -> 0 <= w4 -> BEF L4 p4 (u4 + w4) ->
    evt psegs POST (MS (mkR (Z_to_bv 64 bc2) (Z_to_bv 64 (SP + -416)) gp tp (Z_to_bv 64 (DST + q)) t1 (Z_to_bv 64 (DST + q + 3 * SEG))
                           (Z_to_bv 64 u3) (Z_to_bv 64 w3) (Z_to_bv 64 (SS + O4 + p4)) (Z_to_bv 64 w4) (Z_to_bv 64 bc1) a3 a4 a5
                           (Z_to_bv 64 DST) (Z_to_bv 64 (64 - tl)) (Z_to_bv 64 (DT + 4)) x19 x20 (Z_to_bv 64 (SS + O2 + p2))
                           x22 (Z_to_bv 64 (SS + O3 + p3)) (Z_to_bv 64 (SS + 6 + p1)) (Z_to_bv 64 SEG) x26 x27
                           (Z_to_bv 64 3) (Z_to_bv 64 st1) (Z_to_bv 64 u4) t6)
